prog='''def components(g):
    H,W=len(g),len(g[0]); seen=set(); comps=[]
    for y in range(H):
        for x in range(W):
            if g[y][x] and (y,x) not in seen:
                col=g[y][x]; st=[(y,x)]; cells=[]
                seen.add((y,x))
                while st:
                    cy,cx=st.pop(); cells.append((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                comps.append((col,cells))
    return comps

def has_hole(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    inside={(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1)}-set(cells)
    ext=set(); st=[]
    for p in list(inside):
        if p[0] in (y0,y1) or p[1] in (x0,x1): st.append(p); ext.add(p)
    while st:
        cy,cx=st.pop()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(cy+dy,cx+dx)
            if p in inside and p not in ext: ext.add(p); st.append(p)
    return bool(inside-ext)

def transform(grid):
    g=grid
    H,W=len(g),len(g[0]); out=[[0]*W for _ in range(H)]
    ups,downs=[],[]
    for c,cells in components(g):
        ys=[y for y,x in cells]
        (ups if has_hole(cells) else downs).append((min(ys),max(ys),c,cells))
    occ=set()
    def ok(cells): return not any(p in occ for p in cells)
    for top,bot,c,cells in sorted(downs,key=lambda t:-t[1]):
        s=H-1-bot
        while s>0 and not ok([(y+s,x) for y,x in cells]): s-=1
        for y,x in cells: occ.add((y+s,x)); out[y+s][x]=c
    for top,bot,c,cells in sorted(ups,key=lambda t:t[0]):
        s=top
        while s>0 and not ok([(y-s,x) for y,x in cells]): s-=1
        for y,x in cells: occ.add((y-s,x)); out[y-s][x]=c
    return out
'''
